/* ============================================================
   SECTION 1: Random Module
   ============================================================ */
+ '<h2 class="l-title">1. Random Module</h2>'

+ '<p class="l-text">NumPy\u2019s random module was completely redesigned in version 1.17. The new API centers around <strong>Generator objects</strong> created by <code>np.random.default_rng()</code>. The old API (<code>np.random.rand</code>, <code>np.random.randint</code>) still works but is considered legacy. The new API is faster, more flexible, and statistically better.</p>'

+ '<div class="calc-cards">'
+ '<div class="calc-card"><div class="card-title">default_rng()</div><div class="card-body">Creates a Generator with the PCG64 bit generator. Pass a seed for reproducibility: <code>rng = np.random.default_rng(42)</code></div></div>'
+ '<div class="calc-card"><div class="card-title">integers()</div><div class="card-body">Random integers from low (inclusive) to high (exclusive). Replaces <code>randint</code>.</div></div>'
+ '<div class="calc-card"><div class="card-title">random()</div><div class="card-body">Uniform floats in [0, 1). Replaces <code>rand</code> and <code>random_sample</code>.</div></div>'
+ '<div class="calc-card"><div class="card-title">choice()</div><div class="card-body">Random selection from an array, with or without replacement. Supports probability weights.</div></div>'
+ '</div>'

+ '<div class="code-wrap"><div class="code-label"><span>PYTHON</span><button class="copy-btn" onclick="navigator.clipboard.writeText(this.closest(\'.code-wrap\').querySelector(\'code\').textContent)">COPY</button></div><pre class="code-block"><code><span class="kw">import</span> numpy <span class="kw">as</span> np\n\n<span class="cm"># ---- New API (recommended) ----</span>\nrng = np.random.<span class="fn">default_rng</span>(<span class="num">42</span>)   <span class="cm"># seeded for reproducibility</span>\n\n<span class="cm"># Random integers: low (inclusive) to high (exclusive)</span>\n<span class="fn">print</span>(rng.<span class="fn">integers</span>(<span class="num">0</span>, <span class="num">10</span>, size=<span class="num">5</span>))       <span class="cm"># e.g. [0 7 6 4 4]</span>\n<span class="fn">print</span>(rng.<span class="fn">integers</span>(<span class="num">0</span>, <span class="num">10</span>, size=(<span class="num">2</span>,<span class="num">3</span>)))   <span class="cm"># 2x3 matrix</span>\n\n<span class="cm"># Uniform floats in [0, 1)</span>\n<span class="fn">print</span>(rng.<span class="fn">random</span>((<span class="num">3</span>,)))                   <span class="cm"># e.g. [0.123, 0.876, 0.541]</span>\n\n<span class="cm"># Choice: pick from array</span>\ncolors = np.<span class="fn">array</span>([<span class="str">\'red\'</span>, <span class="str">\'blue\'</span>, <span class="str">\'green\'</span>, <span class="str">\'yellow\'</span>])\n<span class="fn">print</span>(rng.<span class="fn">choice</span>(colors, size=<span class="num">3</span>))          <span class="cm"># with replacement</span>\n<span class="fn">print</span>(rng.<span class="fn">choice</span>(colors, size=<span class="num">3</span>, replace=<span class="kw">False</span>))  <span class="cm"># without replacement</span>\n\n<span class="cm"># Weighted choice (probability distribution over items)</span>\nweights = [<span class="num">0.5</span>, <span class="num">0.3</span>, <span class="num">0.15</span>, <span class="num">0.05</span>]\n<span class="fn">print</span>(rng.<span class="fn">choice</span>(colors, size=<span class="num">6</span>, p=weights))\n\n<span class="cm"># Shuffle and permutation</span>\narr = np.<span class="fn">arange</span>(<span class="num">10</span>)\nrng.<span class="fn">shuffle</span>(arr)                <span class="cm"># in-place shuffle</span>\n<span class="fn">print</span>(arr)                      <span class="cm"># e.g. [3 7 0 9 1 5 4 6 2 8]</span>\n\nperm = rng.<span class="fn">permutation</span>(<span class="num">10</span>)     <span class="cm"># returns new array, original unchanged</span>\n<span class="fn">print</span>(perm)</code></pre></div>'

+ '<p class="l-text"><strong>Seed reproducibility</strong> is essential for scientific computing and debugging. When you pass the same seed, you get the exact same sequence of random numbers every time:</p>'

+ '<div class="code-wrap"><div class="code-label"><span>PYTHON</span><button class="copy-btn" onclick="navigator.clipboard.writeText(this.closest(\'.code-wrap\').querySelector(\'code\').textContent)">COPY</button></div><pre class="code-block"><code><span class="kw">import</span> numpy <span class="kw">as</span> np\n\n<span class="cm"># Same seed \u2192 same numbers every time</span>\nrng1 = np.random.<span class="fn">default_rng</span>(<span class="num">42</span>)\nrng2 = np.random.<span class="fn">default_rng</span>(<span class="num">42</span>)\n\n<span class="fn">print</span>(rng1.<span class="fn">random</span>(<span class="num">5</span>))    <span class="cm"># [0.773... 0.438... 0.858... 0.697... 0.094...]</span>\n<span class="fn">print</span>(rng2.<span class="fn">random</span>(<span class="num">5</span>))    <span class="cm"># identical output!</span>\n\n<span class="cm"># Independent streams for parallel work</span>\nrng_a = np.random.<span class="fn">default_rng</span>(<span class="num">100</span>)\nrng_b = np.random.<span class="fn">default_rng</span>(<span class="num">200</span>)\n<span class="cm"># Each stream produces independent sequences</span></code></pre></div>'

+ '<div class="calc-compare">'
+ '<div class="compare-col"><div class="compare-title">OLD API (Legacy)</div>'
+ '<div class="compare-item">np.random.seed(42)</div>'
+ '<div class="compare-item">np.random.randint(0, 10)</div>'
+ '<div class="compare-item">np.random.rand(3, 4)</div>'
+ '<div class="compare-item">np.random.randn(3, 4)</div>'
+ '<div class="compare-item">np.random.choice(arr)</div>'
+ '<div class="compare-item">np.random.shuffle(arr)</div></div>'
+ '<div class="compare-col"><div class="compare-title">NEW API (Recommended)</div>'
+ '<div class="compare-item">rng = default_rng(42)</div>'
+ '<div class="compare-item">rng.integers(0, 10)</div>'
+ '<div class="compare-item">rng.random((3, 4))</div>'
+ '<div class="compare-item">rng.standard_normal((3, 4))</div>'
+ '<div class="compare-item">rng.choice(arr)</div>'
+ '<div class="compare-item">rng.shuffle(arr)</div></div>'
+ '</div>'

+ '<div class="l-note"><strong>Why the new API?</strong> The old API uses a global state (<code>np.random.seed</code>) that creates hidden dependencies between functions. If two libraries both call <code>np.random.seed</code>, they interfere with each other. The new Generator API uses <strong>independent instances</strong> \u2014 each with its own state \u2014 eliminating this problem entirely.</div>'

/* ============================================================
   SECTION 2: Probability Distributions
   ============================================================ */
+ '<h2 class="l-title">2. Probability Distributions</h2>'

+ '<p class="l-text">The Generator object provides methods for sampling from all major probability distributions. Each distribution has parameters that control its shape, and understanding them is crucial for ML \u2014 weight initialization, noise injection, data augmentation, and Bayesian methods all rely on these distributions.</p>'

+ '<p class="l-text"><strong>Uniform distribution PDF \u2014 equal probability across an interval:</strong></p>'
+ '<div class="katex-block">$$f(x) = \\frac{1}{b - a}, \\quad a \\le x \\le b$$</div>'
+ '<div class="calc-cards">'
+ '<div class="calc-card"><div class="card-title">f(x)</div><div class="card-body">Probability density. For uniform it is a flat constant inside [a, b] and zero outside.</div></div>'
+ '<div class="calc-card"><div class="card-title">a, b</div><div class="card-body">Lower and upper bounds of the interval. b > a required.</div></div>'
+ '<div class="calc-card"><div class="card-title">1/(b\u2212a)</div><div class="card-body">Constant density chosen so the total area under the rectangle equals 1, making it a valid PDF.</div></div>'
+ '<div class="calc-card"><div class="card-title">Use in ML</div><div class="card-body">Random search, parameter initialization in some networks (e.g., Xavier uniform), and dropout sampling.</div></div>'
+ '</div>'

+ '<p class="l-text"><strong>Normal (Gaussian) distribution PDF \u2014 the bell curve:</strong></p>'
+ '<div class="katex-block">$$f(x) = \\frac{1}{\\sigma\\sqrt{2\\pi}} \\exp\\!\\left(-\\frac{(x-\\mu)^2}{2\\sigma^2}\\right)$$</div>'
+ '<div class="calc-cards">'
+ '<div class="calc-card"><div class="card-title">\u03bc</div><div class="card-body">Mean \u2014 center of the distribution. Shifts the curve left/right but not its shape.</div></div>'
+ '<div class="calc-card"><div class="card-title">\u03c3</div><div class="card-body">Standard deviation \u2014 spread. Larger \u03c3 widens the curve; smaller \u03c3 makes it taller and narrower.</div></div>'
+ '<div class="calc-card"><div class="card-title">exp(...)</div><div class="card-body">Exponential decay term that gives the bell shape. Squared deviation guarantees symmetry; division by 2\u03c3\u00b2 controls how fast probability decays.</div></div>'
+ '<div class="calc-card"><div class="card-title">Why so common</div><div class="card-body">Central Limit Theorem: sums of many independent random variables tend toward normal. That is why normal noise dominates in ML and physics.</div></div>'
+ '</div>'

+ '<p class="l-text"><strong>Binomial distribution PMF \u2014 number of successes in n independent trials:</strong></p>'
+ '<div class="katex-block">$$P(X = k) = \\binom{n}{k} p^{k} (1-p)^{n-k}$$</div>'
+ '<div class="calc-cards">'
+ '<div class="calc-card"><div class="card-title">P(X=k)</div><div class="card-body">Probability of getting exactly k successes out of n trials. Discrete distribution.</div></div>'
+ '<div class="calc-card"><div class="card-title">n</div><div class="card-body">Total number of independent trials (e.g., coin flips). Fixed in advance.</div></div>'
+ '<div class="calc-card"><div class="card-title">p</div><div class="card-body">Probability of success on a single trial. (1\u2212p) is the probability of failure.</div></div>'
+ '<div class="calc-card"><div class="card-title">C(n,k)</div><div class="card-body">Binomial coefficient n!/(k!(n\u2212k)!) \u2014 counts the number of distinct ways to arrange k successes among n trials.</div></div>'
+ '<div class="calc-card"><div class="card-title">Use in ML</div><div class="card-body">Modeling A/B tests, dropout masks (each unit kept with probability p), label noise modeling.</div></div>'
+ '</div>'

+ '<p class="l-text"><strong>Poisson distribution PMF \u2014 rare event count over a fixed interval:</strong></p>'
+ '<div class="katex-block">$$P(X = k) = \\frac{\\lambda^{k} e^{-\\lambda}}{k!}$$</div>'
+ '<div class="calc-cards">'
+ '<div class="calc-card"><div class="card-title">P(X=k)</div><div class="card-body">Probability of exactly k events occurring in a fixed time/space interval, when events occur independently at a constant average rate.</div></div>'
+ '<div class="calc-card"><div class="card-title">\u03bb (lambda)</div><div class="card-body">Average rate (mean number of events per interval). Both mean and variance equal \u03bb \u2014 a defining property.</div></div>'
+ '<div class="calc-card"><div class="card-title">k!</div><div class="card-body">Factorial of k = k\u00b7(k\u22121)\u00b7...\u00b71. Normalizes for the order in which events could occur.</div></div>'
+ '<div class="calc-card"><div class="card-title">Examples</div><div class="card-body">Number of website visits per minute, typos per page, photons hitting a sensor per second, rare word occurrences in a corpus.</div></div>'
+ '</div>'

+ '<div class="calc-steps">'
+ '<div class="calc-step"><div class="step-num">1</div><div class="step-content"><div class="step-title">Normal (Gaussian)</div><div class="step-detail"><code>rng.normal(loc=0, scale=1, size)</code> \u2014 Bell curve centered at <code>loc</code> (mean) with spread <code>scale</code> (std dev). Used for weight initialization, noise, and modeling natural phenomena.</div></div></div>'
+ '<div class="calc-step"><div class="step-num">2</div><div class="step-content"><div class="step-title">Uniform</div><div class="step-detail"><code>rng.uniform(low=0, high=1, size)</code> \u2014 Equal probability across [low, high). Used for random search, data augmentation, and initializing parameters.</div></div></div>'
+ '<div class="calc-step"><div class="step-num">3</div><div class="step-content"><div class="step-title">Binomial</div><div class="step-detail"><code>rng.binomial(n, p, size)</code> \u2014 Number of successes in <code>n</code> trials with success probability <code>p</code>. Models yes/no experiments: coin flips, A/B tests, dropout masks.</div></div></div>'
+ '<div class="calc-step"><div class="step-num">4</div><div class="step-content"><div class="step-title">Poisson</div><div class="step-detail"><code>rng.poisson(lam, size)</code> \u2014 Number of events in a fixed interval with rate <code>lam</code>. Models website visits, particle decay, customer arrivals.</div></div></div>'
+ '<div class="calc-step"><div class="step-num">5</div><div class="step-content"><div class="step-title">Exponential</div><div class="step-detail"><code>rng.exponential(scale, size)</code> \u2014 Time between events in a Poisson process. <code>scale</code> = 1/rate. Models waiting times and decay.</div></div></div>'
+ '</div>'

+ '<div class="code-wrap"><div class="code-label"><span>PYTHON</span><button class="copy-btn" onclick="navigator.clipboard.writeText(this.closest(\'.code-wrap\').querySelector(\'code\').textContent)">COPY</button></div><pre class="code-block"><code><span class="kw">import</span> numpy <span class="kw">as</span> np\n\nrng = np.random.<span class="fn">default_rng</span>(<span class="num">42</span>)\n\n<span class="cm"># Normal: mean=0, std=1 (standard normal)</span>\nnormal_samples = rng.<span class="fn">normal</span>(loc=<span class="num">0</span>, scale=<span class="num">1</span>, size=<span class="num">10000</span>)\n<span class="fn">print</span>(f<span class="str">"Mean: {normal_samples.mean():.3f}, Std: {normal_samples.std():.3f}"</span>)\n<span class="cm"># Mean: ~0.000, Std: ~1.000</span>\n\n<span class="cm"># Normal with custom parameters (e.g., height distribution)</span>\nheights = rng.<span class="fn">normal</span>(loc=<span class="num">170</span>, scale=<span class="num">10</span>, size=<span class="num">1000</span>)  <span class="cm"># cm</span>\n\n<span class="cm"># Uniform in [0, 10)</span>\nuniform_samples = rng.<span class="fn">uniform</span>(low=<span class="num">0</span>, high=<span class="num">10</span>, size=<span class="num">10000</span>)\n\n<span class="cm"># Binomial: 10 coin flips, P(heads)=0.5, 1000 experiments</span>\nflips = rng.<span class="fn">binomial</span>(n=<span class="num">10</span>, p=<span class="num">0.5</span>, size=<span class="num">1000</span>)\n<span class="fn">print</span>(f<span class="str">"Average heads in 10 flips: {flips.mean():.2f}"</span>)  <span class="cm"># ~5.00</span>\n\n<span class="cm"># Poisson: average 4 events per interval</span>\nevents = rng.<span class="fn">poisson</span>(lam=<span class="num">4</span>, size=<span class="num">10000</span>)\n\n<span class="cm"># Exponential: average wait time = 2</span>\nwaits = rng.<span class="fn">exponential</span>(scale=<span class="num">2</span>, size=<span class="num">10000</span>)</code></pre></div>'

/* --- Plotly: Probability Distributions (EN) --- */
