+ 'var layout={title:{text:"Random Walk Simulation (5 walkers, 200 steps)",font:{color:"#ebe6dc",size:14}},paper_bgcolor:"rgba(0,0,0,0)",plot_bgcolor:"rgba(0,0,0,0)",font:{color:"#ebe6dc"},xaxis:{title:"Step",gridcolor:"rgba(255,255,255,0.06)"},yaxis:{title:"Position",gridcolor:"rgba(255,255,255,0.06)",zeroline:true,zerolinecolor:"rgba(255,255,255,0.15)"},margin:{t:50,r:30,b:50,l:60},legend:{font:{color:"#ebe6dc"}}};'
