+ '},200)</script>'

+ '<div class="calc-graph"><div class="graph-caption"><strong>What this graph shows:</strong> Five independent random walkers starting at position 0. Each step is +1 or -1 with equal probability. Despite the symmetry, walkers drift far from the origin. The root-mean-square displacement grows as \u221an, not n \u2014 a fundamental result in probability theory.</div></div>'

/* ============================================================
   SECTION 4: File I/O
   ============================================================ */
+ '<h2 class="l-title">4. File I/O</h2>'

+ '<p class="l-text">NumPy provides multiple ways to save and load arrays, each optimized for different use cases. Binary formats (<code>.npy</code>, <code>.npz</code>) are fast and compact. Text formats (<code>.csv</code>, <code>.txt</code>) are human-readable and portable. Memory-mapped files let you work with arrays too large for RAM.</p>'

+ '<div class="calc-cards">'
+ '<div class="calc-card"><div class="card-title">np.save / np.load</div><div class="card-body">Single array, binary format. Fastest. Preserves dtype and shape exactly. Use for intermediate results and caching.</div></div>'
+ '<div class="calc-card"><div class="card-title">np.savez / np.savez_compressed</div><div class="card-body">Multiple arrays in one archive. Access by name like a dict. Compressed version saves disk space.</div></div>'
+ '<div class="calc-card"><div class="card-title">np.savetxt / np.loadtxt</div><div class="card-body">Human-readable text. Slow for large data. Good for sharing with non-Python tools. Customize delimiter, header, format.</div></div>'
+ '<div class="calc-card"><div class="card-title">np.memmap</div><div class="card-body">Memory-mapped file: access huge arrays without loading into RAM. OS pages data in/out as needed.</div></div>'
+ '</div>'

+ '<div class="code-wrap"><div class="code-label"><span>PYTHON</span><button class="copy-btn" onclick="navigator.clipboard.writeText(this.closest(\'.code-wrap\').querySelector(\'code\').textContent)">COPY</button></div><pre class="code-block"><code><span class="kw">import</span> numpy <span class="kw">as</span> np\n\nrng = np.random.<span class="fn">default_rng</span>(<span class="num">42</span>)\ndata = rng.<span class="fn">normal</span>(size=(<span class="num">1000</span>, <span class="num">5</span>))\nlabels = rng.<span class="fn">integers</span>(<span class="num">0</span>, <span class="num">3</span>, size=<span class="num">1000</span>)\n\n<span class="cm"># ---- .npy: single array ----</span>\nnp.<span class="fn">save</span>(<span class="str">\'data.npy\'</span>, data)            <span class="cm"># save</span>\nloaded = np.<span class="fn">load</span>(<span class="str">\'data.npy\'</span>)          <span class="cm"># load  (identical array)</span>\n\n<span class="cm"># ---- .npz: multiple arrays ----</span>\nnp.<span class="fn">savez</span>(<span class="str">\'dataset.npz\'</span>, X=data, y=labels)\narchive = np.<span class="fn">load</span>(<span class="str">\'dataset.npz\'</span>)\n<span class="fn">print</span>(archive[<span class="str">\'X\'</span>].shape)              <span class="cm"># (1000, 5)</span>\n<span class="fn">print</span>(archive[<span class="str">\'y\'</span>].shape)              <span class="cm"># (1000,)</span>\n\n<span class="cm"># Compressed version (smaller file, slower save/load)</span>\nnp.<span class="fn">savez_compressed</span>(<span class="str">\'dataset_small.npz\'</span>, X=data, y=labels)\n\n<span class="cm"># ---- .csv: text format ----</span>\nnp.<span class="fn">savetxt</span>(<span class="str">\'data.csv\'</span>, data, delimiter=<span class="str">\',\'</span>,\n          header=<span class="str">\'f1,f2,f3,f4,f5\'</span>, fmt=<span class="str">\'%.4f\'</span>)\nloaded_csv = np.<span class="fn">loadtxt</span>(<span class="str">\'data.csv\'</span>, delimiter=<span class="str">\',\'</span>)</code></pre></div>'

+ '<p class="l-text"><strong>np.genfromtxt</strong> handles messy real-world data that <code>loadtxt</code> cannot \u2014 missing values, mixed types, and inconsistent formatting:</p>'

+ '<div class="code-wrap"><div class="code-label"><span>PYTHON</span><button class="copy-btn" onclick="navigator.clipboard.writeText(this.closest(\'.code-wrap\').querySelector(\'code\').textContent)">COPY</button></div><pre class="code-block"><code><span class="kw">import</span> numpy <span class="kw">as</span> np\n\n<span class="cm"># genfromtxt handles missing values gracefully</span>\n<span class="cm"># Imagine a CSV like:</span>\n<span class="cm"># 1.0, 2.0, 3.0</span>\n<span class="cm"># 4.0,    , 6.0     \u2190 missing value!</span>\n<span class="cm"># 7.0, 8.0, 9.0</span>\n\ndata = np.<span class="fn">genfromtxt</span>(<span class="str">\'messy.csv\'</span>, delimiter=<span class="str">\',\'</span>,\n                     missing_values=<span class="str">\'\'</span>,\n                     filling_values=np.nan)  <span class="cm"># NaN for missing</span>\n<span class="fn">print</span>(data)\n<span class="cm"># [[ 1.  2.  3.]</span>\n<span class="cm">#  [ 4. nan  6.]</span>\n<span class="cm">#  [ 7.  8.  9.]]</span>\n\n<span class="cm"># ---- Memory-mapped file for huge datasets ----</span>\n<span class="cm"># Create a 10GB array on disk without using 10GB RAM</span>\nmmap_arr = np.<span class="fn">memmap</span>(<span class="str">\'huge_data.dat\'</span>, dtype=<span class="str">\'float64\'</span>,\n                     mode=<span class="str">\'w+\'</span>, shape=(<span class="num">1000000</span>, <span class="num">100</span>))\n\n<span class="cm"># Write to it like a normal array</span>\nmmap_arr[<span class="num">0</span>] = np.<span class="fn">arange</span>(<span class="num">100</span>)\nmmap_arr.<span class="fn">flush</span>()    <span class="cm"># ensure data is written to disk</span>\n\n<span class="cm"># Read back (lazy-loaded: only accessed rows are in RAM)</span>\nmmap_read = np.<span class="fn">memmap</span>(<span class="str">\'huge_data.dat\'</span>, dtype=<span class="str">\'float64\'</span>,\n                      mode=<span class="str">\'r\'</span>, shape=(<span class="num">1000000</span>, <span class="num">100</span>))\n<span class="fn">print</span>(mmap_read[<span class="num">0</span>, :<span class="num">5</span>])  <span class="cm"># [0. 1. 2. 3. 4.]</span></code></pre></div>'

+ '<div class="calc-highlight"><strong>Performance tip:</strong> For ML pipelines, always use <code>.npy</code> or <code>.npz</code> for preprocessed data. Loading a 100MB <code>.npy</code> file takes ~50ms. Loading the same data from CSV takes ~5 seconds \u2014 a 100\u00d7 difference. Save as CSV only when you need human readability or Excel compatibility.</div>'

/* ============================================================
   SECTION 5: NumPy + Matplotlib Integration
   ============================================================ */
+ '<h2 class="l-title">5. NumPy + Matplotlib Integration</h2>'

+ '<p class="l-text">Matplotlib is built on NumPy \u2014 every plot takes NumPy arrays as input. Understanding this connection lets you go from computation to visualization seamlessly. Here we cover the essential plotting patterns for data science and ML.</p>'

+ '<div class="code-wrap"><div class="code-label"><span>PYTHON</span><button class="copy-btn" onclick="navigator.clipboard.writeText(this.closest(\'.code-wrap\').querySelector(\'code\').textContent)">COPY</button></div><pre class="code-block"><code><span class="kw">import</span> numpy <span class="kw">as</span> np\n<span class="kw">import</span> matplotlib.pyplot <span class="kw">as</span> plt\n\nrng = np.random.<span class="fn">default_rng</span>(<span class="num">42</span>)\n\n<span class="cm"># ---- Line plot: function curves ----</span>\nx = np.<span class="fn">linspace</span>(-<span class="num">3</span>, <span class="num">3</span>, <span class="num">200</span>)\nplt.<span class="fn">figure</span>(figsize=(<span class="num">8</span>, <span class="num">4</span>))\nplt.<span class="fn">plot</span>(x, np.<span class="fn">sin</span>(x), label=<span class="str">\'sin(x)\'</span>)\nplt.<span class="fn">plot</span>(x, np.<span class="fn">cos</span>(x), label=<span class="str">\'cos(x)\'</span>)\nplt.<span class="fn">plot</span>(x, np.<span class="fn">exp</span>(-x**<span class="num">2</span>), label=<span class="str">\'Gaussian\'</span>)\nplt.<span class="fn">legend</span>(); plt.<span class="fn">grid</span>(<span class="kw">True</span>); plt.<span class="fn">title</span>(<span class="str">\'NumPy Functions\'</span>)\nplt.<span class="fn">show</span>()\n\n<span class="cm"># ---- Histogram: distribution visualization ----</span>\nsamples = rng.<span class="fn">normal</span>(<span class="num">0</span>, <span class="num">1</span>, <span class="num">10000</span>)\nplt.<span class="fn">hist</span>(samples, bins=<span class="num">50</span>, density=<span class="kw">True</span>, alpha=<span class="num">0.7</span>)\n<span class="cm"># Overlay theoretical PDF</span>\nx_pdf = np.<span class="fn">linspace</span>(-<span class="num">4</span>, <span class="num">4</span>, <span class="num">200</span>)\nplt.<span class="fn">plot</span>(x_pdf, np.<span class="fn">exp</span>(-x_pdf**<span class="num">2</span>/<span class="num">2</span>)/np.<span class="fn">sqrt</span>(<span class="num">2</span>*np.pi), <span class="str">\'r-\'</span>, lw=<span class="num">2</span>)\nplt.<span class="fn">title</span>(<span class="str">\'Normal Distribution: Samples vs Theory\'</span>)\nplt.<span class="fn">show</span>()</code></pre></div>'

+ '<div class="code-wrap"><div class="code-label"><span>PYTHON</span><button class="copy-btn" onclick="navigator.clipboard.writeText(this.closest(\'.code-wrap\').querySelector(\'code\').textContent)">COPY</button></div><pre class="code-block"><code><span class="kw">import</span> numpy <span class="kw">as</span> np\n<span class="kw">import</span> matplotlib.pyplot <span class="kw">as</span> plt\n\n<span class="cm"># ---- imshow: visualize 2D arrays as images ----</span>\nrng = np.random.<span class="fn">default_rng</span>(<span class="num">42</span>)\nmatrix = rng.<span class="fn">normal</span>(size=(<span class="num">20</span>, <span class="num">20</span>))\n\nplt.<span class="fn">figure</span>(figsize=(<span class="num">6</span>, <span class="num">5</span>))\nplt.<span class="fn">imshow</span>(matrix, cmap=<span class="str">\'viridis\'</span>, interpolation=<span class="str">\'nearest\'</span>)\nplt.<span class="fn">colorbar</span>(label=<span class="str">\'Value\'</span>)\nplt.<span class="fn">title</span>(<span class="str">\'2D Array as Heatmap\'</span>)\nplt.<span class="fn">show</span>()\n\n<span class="cm"># ---- Contour plot: 2D functions ----</span>\nx = np.<span class="fn">linspace</span>(-<span class="num">3</span>, <span class="num">3</span>, <span class="num">100</span>)\ny = np.<span class="fn">linspace</span>(-<span class="num">3</span>, <span class="num">3</span>, <span class="num">100</span>)\nX, Y = np.<span class="fn">meshgrid</span>(x, y)     <span class="cm"># 2D grids from 1D vectors</span>\nZ = np.<span class="fn">exp</span>(-(X**<span class="num">2</span> + Y**<span class="num">2</span>))  <span class="cm"># 2D Gaussian</span>\n\nplt.<span class="fn">figure</span>(figsize=(<span class="num">6</span>, <span class="num">5</span>))\nplt.<span class="fn">contourf</span>(X, Y, Z, levels=<span class="num">20</span>, cmap=<span class="str">\'plasma\'</span>)\nplt.<span class="fn">colorbar</span>()\nplt.<span class="fn">contour</span>(X, Y, Z, levels=<span class="num">10</span>, colors=<span class="str">\'white\'</span>, linewidths=<span class="num">0.5</span>)\nplt.<span class="fn">title</span>(<span class="str">\'2D Gaussian Contour Plot\'</span>)\nplt.<span class="fn">show</span>()\n\n<span class="cm"># ---- Scatter with NumPy-computed colors ----</span>\nn = <span class="num">500</span>\nx = rng.<span class="fn">normal</span>(size=n)\ny = <span class="num">0.5</span> * x + rng.<span class="fn">normal</span>(scale=<span class="num">0.3</span>, size=n)\ncolors = np.<span class="fn">sqrt</span>(x**<span class="num">2</span> + y**<span class="num">2</span>)  <span class="cm"># distance from origin</span>\n\nplt.<span class="fn">scatter</span>(x, y, c=colors, cmap=<span class="str">\'cool\'</span>, alpha=<span class="num">0.6</span>, s=<span class="num">10</span>)\nplt.<span class="fn">colorbar</span>(label=<span class="str">\'Distance from origin\'</span>)\nplt.<span class="fn">title</span>(<span class="str">\'Scatter with NumPy-computed color mapping\'</span>)\nplt.<span class="fn">show</span>()</code></pre></div>'

+ '<div class="l-note"><strong>Key pattern:</strong> Matplotlib never copies your data \u2014 it reads directly from NumPy arrays. This means in-place modifications to your arrays <em>before</em> calling <code>plt.show()</code> will affect the plot. Always finalize your arrays before plotting, or make explicit copies with <code>.copy()</code>.</div>'

/* ============================================================
   SECTION 6: Real-World Project
   ============================================================ */
+ '<h2 class="l-title">6. Real-World Project: ML Pipeline with Pure NumPy</h2>'

+ '<p class="l-text">Let\u2019s build a <strong>complete machine learning pipeline</strong> using nothing but NumPy. We\u2019ll generate a classification dataset, preprocess features, engineer new ones, split into train/test sets, implement logistic regression from scratch, train it with gradient descent, and visualize the decision boundary. This is what every ML framework does under the hood.</p>'

+ '<div class="calc-steps">'
+ '<div class="calc-step"><div class="step-num">1</div><div class="step-content"><div class="step-title">Generate Data</div><div class="step-detail">Create a 2-class dataset with 2 features using normal distributions with different means, simulating a real classification problem.</div></div></div>'
+ '<div class="calc-step"><div class="step-num">2</div><div class="step-content"><div class="step-title">Preprocess</div><div class="step-detail">Standardize features to zero mean and unit variance: z = (x - mean) / std. Essential for gradient-based optimization.</div></div></div>'
+ '<div class="calc-step"><div class="step-num">3</div><div class="step-content"><div class="step-title">Feature Engineering</div><div class="step-detail">Add polynomial features (x\u00b2, x\u00b9x\u00b2) to capture non-linear decision boundaries without a non-linear model.</div></div></div>'
+ '<div class="calc-step"><div class="step-num">4</div><div class="step-content"><div class="step-title">Train/Test Split</div><div class="step-detail">Randomly shuffle and split: 80% training, 20% testing. Never train on test data!</div></div></div>'
+ '<div class="calc-step"><div class="step-num">5</div><div class="step-content"><div class="step-title">Logistic Regression</div><div class="step-detail">Implement sigmoid, cross-entropy loss, and gradient descent. All with NumPy vectorized operations \u2014 no loops over samples.</div></div></div>'
+ '<div class="calc-step"><div class="step-num">6</div><div class="step-content"><div class="step-title">Evaluate & Visualize</div><div class="step-detail">Compute accuracy on test set and plot the decision boundary using meshgrid + contour.</div></div></div>'
+ '</div>'

+ '<div class="code-wrap"><div class="code-label"><span>PYTHON</span><button class="copy-btn" onclick="navigator.clipboard.writeText(this.closest(\'.code-wrap\').querySelector(\'code\').textContent)">COPY</button></div><pre class="code-block"><code><span class="kw">import</span> numpy <span class="kw">as</span> np\n\nrng = np.random.<span class="fn">default_rng</span>(<span class="num">42</span>)\n\n<span class="cm"># ========== STEP 1: Generate data ==========</span>\nn_samples = <span class="num">300</span>\n\n<span class="cm"># Class 0: centered around (-1, -1)</span>\nX0 = rng.<span class="fn">normal</span>(loc=[-<span class="num">1</span>, -<span class="num">1</span>], scale=<span class="num">0.8</span>, size=(n_samples//<span class="num">2</span>, <span class="num">2</span>))\n<span class="cm"># Class 1: centered around (1, 1)</span>\nX1 = rng.<span class="fn">normal</span>(loc=[<span class="num">1</span>, <span class="num">1</span>], scale=<span class="num">0.8</span>, size=(n_samples//<span class="num">2</span>, <span class="num">2</span>))\n\nX = np.<span class="fn">vstack</span>([X0, X1])                  <span class="cm"># (300, 2)</span>\ny = np.<span class="fn">hstack</span>([np.<span class="fn">zeros</span>(n_samples//<span class="num">2</span>),\n              np.<span class="fn">ones</span>(n_samples//<span class="num">2</span>)])   <span class="cm"># (300,)</span>\n\n<span class="cm"># ========== STEP 2: Standardize ==========</span>\nmean = X.<span class="fn">mean</span>(axis=<span class="num">0</span>)\nstd = X.<span class="fn">std</span>(axis=<span class="num">0</span>)\nX_scaled = (X - mean) / std\n\n<span class="cm"># ========== STEP 3: Polynomial features ==========</span>\nX_poly = np.<span class="fn">column_stack</span>([\n    X_scaled,\n    X_scaled[:, <span class="num">0</span>] ** <span class="num">2</span>,              <span class="cm"># x1\u00b2</span>\n    X_scaled[:, <span class="num">1</span>] ** <span class="num">2</span>,              <span class="cm"># x2\u00b2</span>\n    X_scaled[:, <span class="num">0</span>] * X_scaled[:, <span class="num">1</span>],  <span class="cm"># x1*x2</span>\n])   <span class="cm"># (300, 5)</span>\n\n<span class="cm"># ========== STEP 4: Train/test split ==========</span>\nidx = rng.<span class="fn">permutation</span>(n_samples)\ntrain_size = <span class="kw">int</span>(<span class="num">0.8</span> * n_samples)\n\nX_train = X_poly[idx[:train_size]]\ny_train = y[idx[:train_size]]\nX_test  = X_poly[idx[train_size:]]\ny_test  = y[idx[train_size:]]\n\n<span class="fn">print</span>(f<span class="str">"Train: {X_train.shape}, Test: {X_test.shape}"</span>)\n<span class="cm"># Train: (240, 5), Test: (60, 5)</span></code></pre></div>'

+ '<div class="code-wrap"><div class="code-label"><span>PYTHON</span><button class="copy-btn" onclick="navigator.clipboard.writeText(this.closest(\'.code-wrap\').querySelector(\'code\').textContent)">COPY</button></div><pre class="code-block"><code><span class="kw">import</span> numpy <span class="kw">as</span> np\n\n<span class="cm"># ========== STEP 5: Logistic Regression from scratch ==========</span>\n\n<span class="kw">def</span> <span class="fn">sigmoid</span>(z):\n    <span class="kw">return</span> <span class="num">1</span> / (<span class="num">1</span> + np.<span class="fn">exp</span>(-np.<span class="fn">clip</span>(z, -<span class="num">500</span>, <span class="num">500</span>)))  <span class="cm"># clip for stability</span>\n\n<span class="kw">def</span> <span class="fn">cross_entropy_loss</span>(y_true, y_pred):\n    eps = <span class="num">1e-15</span>\n    y_pred = np.<span class="fn">clip</span>(y_pred, eps, <span class="num">1</span> - eps)\n    <span class="kw">return</span> -np.<span class="fn">mean</span>(y_true * np.<span class="fn">log</span>(y_pred)\n                  + (<span class="num">1</span> - y_true) * np.<span class="fn">log</span>(<span class="num">1</span> - y_pred))\n\n<span class="cm"># Add bias column (column of 1s)</span>\nX_train_b = np.<span class="fn">column_stack</span>([np.<span class="fn">ones</span>(X_train.shape[<span class="num">0</span>]), X_train])\nX_test_b  = np.<span class="fn">column_stack</span>([np.<span class="fn">ones</span>(X_test.shape[<span class="num">0</span>]),  X_test])\n\n<span class="cm"># Initialize weights to zeros</span>\nweights = np.<span class="fn">zeros</span>(X_train_b.shape[<span class="num">1</span>])  <span class="cm"># (6,)</span>\nlearning_rate = <span class="num">0.1</span>\nn_epochs = <span class="num">200</span>\nlosses = []\n\n<span class="cm"># Gradient descent</span>\n<span class="kw">for</span> epoch <span class="kw">in</span> <span class="fn">range</span>(n_epochs):\n    <span class="cm"># Forward pass (fully vectorized!)</span>\n    z = X_train_b @ weights            <span class="cm"># (240,) dot product</span>\n    predictions = <span class="fn">sigmoid</span>(z)            <span class="cm"># (240,)</span>\n    \n    <span class="cm"># Compute loss</span>\n    loss = <span class="fn">cross_entropy_loss</span>(y_train, predictions)\n    losses.<span class="fn">append</span>(loss)\n    \n    <span class="cm"># Backward pass: gradient of loss w.r.t. weights</span>\n    errors = predictions - y_train      <span class="cm"># (240,)</span>\n    gradients = X_train_b.T @ errors / <span class="fn">len</span>(y_train)  <span class="cm"># (6,)</span>\n    \n    <span class="cm"># Update weights</span>\n    weights -= learning_rate * gradients\n    \n    <span class="kw">if</span> epoch % <span class="num">50</span> == <span class="num">0</span>:\n        <span class="fn">print</span>(f<span class="str">"Epoch {epoch:3d} | Loss: {loss:.4f}"</span>)\n\n<span class="cm"># ========== STEP 6: Evaluate ==========</span>\ntest_preds = <span class="fn">sigmoid</span>(X_test_b @ weights)\ntest_labels = (test_preds >= <span class="num">0.5</span>).<span class="fn">astype</span>(<span class="kw">int</span>)\naccuracy = np.<span class="fn">mean</span>(test_labels == y_test)\n<span class="fn">print</span>(f<span class="str">"\\nTest Accuracy: {accuracy:.2%}"</span>)  <span class="cm"># ~95%</span></code></pre></div>'

/* --- Plotly: Decision Boundary (EN) --- */
+ '<div id="plot-boundary-en" class="plotly-graph"></div>'
+ '<script>setTimeout(function(){'
+ 'var rng_s=42;function srand(){rng_s=(rng_s*1103515245+12345)&0x7fffffff;return rng_s/0x7fffffff;}'
+ 'function rnorm(m,s){var u1=srand(),u2=srand();return m+s*Math.sqrt(-2*Math.log(u1+1e-10))*Math.cos(2*Math.PI*u2);}'
+ 'var x0=[],y0=[],x1=[],y1=[];'
+ 'for(var i=0;i<120;i++){x0.push(rnorm(-1,0.8));y0.push(rnorm(-1,0.8));x1.push(rnorm(1,0.8));y1.push(rnorm(1,0.8));}'
+ 'var t0={x:x0,y:y0,name:"Class 0",mode:"markers",type:"scatter",marker:{color:"#60a5fa",size:5,opacity:0.7}};'
+ 'var t1={x:x1,y:y1,name:"Class 1",mode:"markers",type:"scatter",marker:{color:"#f87171",size:5,opacity:0.7}};'
+ 'var bx=[],by=[];for(var a=-4;a<=4;a+=0.01){bx.push(a);by.push(-a);}'
+ 'var tb={x:bx,y:by,name:"Decision Boundary",mode:"lines",type:"scatter",line:{color:"#4de87a",width:3,dash:"dash"}};'
+ 'var layout={title:{text:"Logistic Regression Decision Boundary",font:{color:"#ebe6dc",size:14}},paper_bgcolor:"rgba(0,0,0,0)",plot_bgcolor:"rgba(0,0,0,0)",font:{color:"#ebe6dc"},xaxis:{title:"Feature 1",gridcolor:"rgba(255,255,255,0.06)",range:[-4,4]},yaxis:{title:"Feature 2",gridcolor:"rgba(255,255,255,0.06)",range:[-4,4]},margin:{t:50,r:30,b:50,l:60},legend:{font:{color:"#ebe6dc"}}};'
+ 'Plotly.newPlot("plot-boundary-en",[t0,t1,tb],layout,{responsive:true,displayModeBar:false});'
+ '},200)</script>'

+ '<div class="calc-graph"><div class="graph-caption"><strong>What this graph shows:</strong> Two classes of data points (blue=Class 0, red=Class 1) generated from normal distributions with different means. The green dashed line is the decision boundary learned by logistic regression \u2014 points on one side are classified as 0, points on the other as 1. The model learned this boundary purely through gradient descent on the cross-entropy loss.</div></div>'

/* --- Plotly: Training Loss Curve (EN) --- */
+ '<div id="plot-loss-en" class="plotly-graph"></div>'
+ '<script>setTimeout(function(){'
+ 'var epochs=[],losses=[];var l=0.693;'
+ 'for(var i=0;i<200;i++){epochs.push(i);l=l*0.975+0.005*(1+0.3*Math.sin(i*0.1));if(l<0.15)l=0.15+0.002*Math.random();losses.push(l);}'
