+ 'for(var i=-1;i<=5;i+=0.05){x_uni.push(i);y_uni.push(i>=0&&i<=4?0.25:0);}'
+ 'for(var i=0;i<=8;i+=0.05){x_exp.push(i);y_exp.push(0.5*Math.exp(-0.5*i));}'
