+ 'var layout={title:{text:"Lojistik Regresyon Karar S\u0131n\u0131r\u0131",font:{color:"#ebe6dc",size:14}},paper_bgcolor:"rgba(0,0,0,0)",plot_bgcolor:"rgba(0,0,0,0)",font:{color:"#ebe6dc"},xaxis:{title:"\u00d6znitelik 1",gridcolor:"rgba(255,255,255,0.06)",range:[-4,4]},yaxis:{title:"\u00d6znitelik 2",gridcolor:"rgba(255,255,255,0.06)",range:[-4,4]},margin:{t:50,r:30,b:50,l:60},legend:{font:{color:"#ebe6dc"}}};'
+ 'Plotly.newPlot("plot-boundary-tr",[t0,t1,tb],layout,{responsive:true,displayModeBar:false});'
